"""Saved scouting reports (generated by a background job) and their CSV/JSON exports."""

import re
import uuid
from typing import Annotated

from fastapi import APIRouter, Depends, Header, Query, Response
from fastapi.responses import StreamingResponse

from app.api.deps import CurrentUserDep, EnqueueDep, SessionDep, rate_limit
from app.api.routes import AUTH, CONFLICT, ERRORS
from app.auth.ratelimit import EXPORT, REPORT
from app.models import ExportFormat, ReportExport, ReportStatus, SavedReport
from app.reports import service as reports
from app.reports.contracts import (
    ExportOut,
    ExportRequest,
    ReportOut,
    ReportPage,
    ReportRequest,
    ReportSummaryOut,
)
from app.services.errors import ConflictError
from app.storage import Storage, get_storage, opened

router = APIRouter(prefix="/api/v1/reports", tags=["reports"], responses={**ERRORS, **AUTH})
StorageDep = Annotated[Storage, Depends(get_storage)]
IdempotencyHeader = Annotated[
    str | None, Header(alias="Idempotency-Key", min_length=1, max_length=200)
]
MEDIA_TYPES = {ExportFormat.CSV: "text/csv; charset=utf-8", ExportFormat.JSON: "application/json"}


def _export_out(report: SavedReport, export: ReportExport) -> ExportOut:
    out = ExportOut.model_validate(export)
    if export.status == ReportStatus.READY:
        out.download_url = f"/api/v1/reports/{report.id}/exports/{export.id}/download"
    return out


def _report_out(session: SessionDep, report: SavedReport) -> ReportOut:
    out = ReportOut.model_validate(report)
    out.exports = [_export_out(report, e) for e in reports.list_exports(session, report)]
    return out


@router.post("", status_code=202, responses=CONFLICT, dependencies=[Depends(rate_limit(REPORT))])
def create_report(
    body: ReportRequest,
    session: SessionDep,
    user: CurrentUserDep,
    enqueue: EnqueueDep,
    response: Response,
    idempotency_key: IdempotencyHeader = None,
) -> ReportOut:
    """Save a report and generate it in the background. Poll GET /reports/{id}."""
    report, replayed = reports.create_report(
        session, body, user=user, idempotency_key=idempotency_key, enqueue=enqueue
    )
    if replayed:
        response.status_code = 200
        response.headers["Idempotent-Replayed"] = "true"
    return _report_out(session, report)


@router.get("")
def list_reports(
    session: SessionDep,
    user: CurrentUserDep,
    page: Annotated[int, Query(ge=1)] = 1,
    page_size: Annotated[int, Query(ge=1, le=100)] = 25,
) -> ReportPage:
    items, total = reports.list_reports(session, user, page=page, page_size=page_size)
    return ReportPage(
        items=[ReportSummaryOut.model_validate(r) for r in items],
        page=page,
        page_size=page_size,
        total=total,
    )


@router.get("/{report_id}")
def get_report(report_id: uuid.UUID, session: SessionDep, user: CurrentUserDep) -> ReportOut:
    return _report_out(session, reports.get_report(session, report_id, user))


@router.delete("/{report_id}", status_code=204)
def delete_report(
    report_id: uuid.UUID, session: SessionDep, storage: StorageDep, user: CurrentUserDep
) -> Response:
    reports.delete_report(session, storage, reports.get_report(session, report_id, user))
    return Response(status_code=204)


@router.post(
    "/{report_id}/exports",
    status_code=202,
    responses=CONFLICT,
    dependencies=[Depends(rate_limit(EXPORT))],
)
def create_export(
    report_id: uuid.UUID,
    body: ExportRequest,
    session: SessionDep,
    user: CurrentUserDep,
    enqueue: EnqueueDep,
    response: Response,
    idempotency_key: IdempotencyHeader = None,
) -> ExportOut:
    """Generate a CSV or JSON file in the background; download it when ready."""
    report = reports.get_report(session, report_id, user)
    export, replayed = reports.create_export(
        session,
        report,
        body.format,
        user=user,
        idempotency_key=idempotency_key or body.idempotency_key,
        enqueue=enqueue,
    )
    if replayed:
        response.status_code = 200
        response.headers["Idempotent-Replayed"] = "true"
    return _export_out(report, export)


@router.get("/{report_id}/exports/{export_id}")
def get_export(
    report_id: uuid.UUID, export_id: uuid.UUID, session: SessionDep, user: CurrentUserDep
) -> ExportOut:
    report = reports.get_report(session, report_id, user)
    return _export_out(report, reports.get_export(session, report, export_id))


def _filename(report: SavedReport, fmt: ExportFormat) -> str:
    slug = re.sub(r"[^A-Za-z0-9]+", "-", report.title).strip("-").lower()[:60] or "report"
    return f"playbookiq-{slug}.{fmt.value}"


@router.get(
    "/{report_id}/exports/{export_id}/download",
    response_class=StreamingResponse,
    responses={200: {"content": {"text/csv": {}, "application/json": {}}}, **CONFLICT},
)
def download_export(
    report_id: uuid.UUID,
    export_id: uuid.UUID,
    session: SessionDep,
    storage: StorageDep,
    user: CurrentUserDep,
) -> Response:
    report = reports.get_report(session, report_id, user)
    export = reports.get_export(session, report, export_id)
    if export.status != ReportStatus.READY or export.storage_key is None:
        raise ConflictError(
            "export_not_ready", f"Export is {export.status.value}", {"status": export.status.value}
        )
    with opened(storage, export.storage_key) as f:
        data = f.read()
    return Response(
        content=data,
        media_type=MEDIA_TYPES[export.format],
        headers={
            "Content-Disposition": f'attachment; filename="{_filename(report, export.format)}"',
            "X-Content-Type-Options": "nosniff",
            "Cache-Control": "private, no-store",
        },
    )
